<main>
<section id="hours" class="bl-section" aria-labelledby="hours-title">
  <div class="bl-wrap">
    <h2 id="hours-title">Opening hours</h2>
    <p>Open every day. Today is highlighted.</p>
    <table class="bl-hours">
      <tbody>
        <tr data-day="1"><th scope="row">Monday</th><td>8am to 10pm</td></tr>
        <tr data-day="2"><th scope="row">Tuesday</th><td>8am to 10pm</td></tr>
        <tr data-day="3"><th scope="row">Wednesday</th><td>8am to 10pm</td></tr>
        <tr data-day="4"><th scope="row">Thursday</th><td>8am to 10pm</td></tr>
        <tr data-day="5"><th scope="row">Friday</th><td>8am to 10pm</td></tr>
        <tr data-day="6"><th scope="row">Saturday</th><td>9am to 11pm</td></tr>
        <tr data-day="0"><th scope="row">Sunday</th><td>9am to 11pm</td></tr>
      </tbody>
    </table>
  </div>
</section>
<!-- Other agents' sections follow this one; the page assembler closes <main> after the last section. -->

<script>
(function () {
  var NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var WEEKDAY = { open: '08:00', close: '22:00' };
  var WEEKEND = { open: '09:00', close: '23:00' };

  function toMin(s) { var p = s.split(':'); return Number(p[0]) * 60 + Number(p[1]); }

  var days = NAMES.map(function (name, i) {
    var h = (i === 0 || i === 6) ? WEEKEND : WEEKDAY;
    return { index: i, name: name, open: h.open, close: h.close, openMin: toMin(h.open), closeMin: toMin(h.close) };
  });

  // Current day (0 = Sunday) and minutes since midnight, in Bengaluru time (Asia/Kolkata).
  function now() {
    try {
      var parts = new Intl.DateTimeFormat('en-US', {
        timeZone: 'Asia/Kolkata', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false
      }).formatToParts(new Date());
      var map = {};
      parts.forEach(function (p) { map[p.type] = p.value; });
      var idx = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(map.weekday);
      if (idx > -1) {
        return { day: idx, minutes: (Number(map.hour) % 24) * 60 + Number(map.minute) };
      }
    } catch (e) { /* fall through to local time */ }
    var d = new Date();
    return { day: d.getDay(), minutes: d.getHours() * 60 + d.getMinutes() };
  }

  // Shared with other sections, e.g. the pre-order form validates pickup time against forDay().
  window.BrewLab = window.BrewLab || {};
  window.BrewLab.hours = {
    days: days,
    forDay: function (i) { return days[i]; },
    now: now,
    today: function () { return days[now().day]; }
  };

  function highlightToday() {
    var rows = document.querySelectorAll('#hours .bl-hours tr[data-day]');
    var today = now().day;
    Array.prototype.forEach.call(rows, function (row) {
      var badge = row.querySelector('.bl-badge');
      if (Number(row.getAttribute('data-day')) === today) {
        row.classList.add('today');
        row.setAttribute('aria-current', 'date');
        if (!badge) {
          badge = document.createElement('span');
          badge.className = 'bl-badge';
          badge.textContent = 'Today';
          row.querySelector('th').appendChild(badge);
        }
      } else {
        row.classList.remove('today');
        row.removeAttribute('aria-current');
        if (badge) { badge.parentNode.removeChild(badge); }
      }
    });
  }

  // Header nav lists only sections that exist, so no in-page link can be broken.
  function buildNav() {
    var nav = document.getElementById('bl-nav');
    if (!nav) { return; }
    nav.innerHTML = '';
    [['hours', 'Hours'], ['menu', 'Menu'], ['preorder', 'Pre-order'], ['loyalty', 'Loyalty'], ['location', 'Location']]
      .forEach(function (item) {
        if (document.getElementById(item[0])) {
          var a = document.createElement('a');
          a.href = '#' + item[0];
          a.textContent = item[1];
          nav.appendChild(a);
        }
      });
  }

  highlightToday();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', buildNav);
  } else {
    buildNav();
  }
  document.addEventListener('visibilitychange', function () {
    if (!document.hidden) { highlightToday(); }
  });
})();
</script>
